"""Curated learning resources (official sources, deep links) - no URL is ever generated by the LLM.

`CATALOG` maps a technology to: what it is, key concepts, the official documentation and direct links to the pages
that matter for beginners. Unknown technologies get NO link (never a guessed one). Everything here works offline.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field

from rag import retriever


@dataclass
class Entry:
    key: str
    name: str
    what: str
    official: tuple[str, str]                  # (source name, url)
    concepts: list[str] = field(default_factory=list)
    links: list[tuple[str, str, str]] = field(default_factory=list)   # (title, url, source)


CATALOG: dict[str, Entry] = {}
ALIAS: dict[str, str] = {}


def _add(key, name, what, src, url, concepts, links, aliases=()):
    CATALOG[key] = Entry(key, name, what, (src, url), list(concepts), [(t, u, s) for t, u, s in links])
    for a in (key, name.lower(), *aliases):
        ALIAS[a.lower()] = key


