_TOKEN = re.compile(r"[^a-z0-9+#.\- ]")


def _norm(s: str) -> str:
    return re.sub(r"\s+", " ", _TOKEN.sub(" ", s.lower())).strip()


def _merge_extra() -> None:
    """Add the technologies in catalog_extra.py; for technologies that already exist only add links/aliases (no duplicates)."""
    from learning import catalog_extra
    for key, name, what, src, url, concepts, links, aliases in catalog_extra.ENTRIES:
        full = [(l[0], l[1], l[2] if len(l) > 2 else src) for l in links]
        if key in CATALOG:
            _extend(key, full)
            for a in aliases:
                ALIAS.setdefault(_norm(a), key)
        else:
            _add(key, name, what, src, url, concepts, full, ())
            for a in (key, name, *aliases):
                ALIAS[_norm(a)] = key
    for key, links in catalog_extra.ENRICH.items():
        if key in CATALOG:
            _extend(key, [(l[0], l[1], l[2] if len(l) > 2 else CATALOG[key].official[0]) for l in links])


def _extend(key: str, links: list[tuple[str, str, str]]) -> None:
    e = CATALOG[key]
    have = {u for _t, u, _s in e.links} | {e.official[1]}
    e.links += [l for l in links if l[1] not in have]


def _dedupe_all() -> None:
    """Data hygiene: no entry lists its official page or the same URL twice."""
    for e in CATALOG.values():
        seen, clean = {e.official[1]}, []
        for t, u, src in e.links:
            if u not in seen:
                seen.add(u)
                clean.append((t, u, src))
        e.links = clean


_merge_extra()
_dedupe_all()


def find_entry(tool: str) -> Entry | None:
    key = _norm(tool)
    if key in ALIAS:
        return CATALOG[ALIAS[key]]
    for alias in sorted(ALIAS, key=len, reverse=True):
        if len(alias) > 2 and re.search(rf"(?<![\w]){re.escape(alias)}(?![\w])", key):
            return CATALOG[ALIAS[alias]]
    return None


def find_entries(tool: str) -> list[Entry]:
    """Like find_entry, but 'Git and GitHub' or 'NumPy / Pandas' resolve to every technology named."""
    whole = find_entry(tool) if _norm(tool) in ALIAS else None
    if whole:
        return [whole]
    parts = [p for p in re.split(r"\s+(?:and|&)\s+|/|,|\+", tool, flags=re.I) if p.strip()]
    found: list[Entry] = []
    for part in parts if len(parts) > 1 else [tool]:
        e = find_entry(part)
        if e and e not in found:
            found.append(e)
    return found


def find_doc(tool: str) -> str:
    """Official documentation URL ('' when the technology is not in the catalog)."""
    es = find_entries(tool)
    return es[0].official[1] if es else ""


def _mdl(title: str, url: str) -> str:
    """Markdown link; brackets in a title would break the syntax."""
    return f"[{title.replace('[', '(').replace(']', ')')}]({url})"


def entry_lines(e: Entry, seen: set[str], max_learn: int = 2) -> list[str]:
    """The display format used everywhere (clickable titles, shown as links by the interface):

        Official Documentation – [Python documentation](https://...)
        Start with – [The Python Tutorial](https://...)

    `seen` removes duplicates across a whole list (e.g. two tools that share a documentation page)."""
    lines = []
    if e.official[1] not in seen:
        seen.add(e.official[1])
        lines.append(f"Official Documentation – {_mdl(e.official[0], e.official[1])}")
    n = 0
    for title, url, src in e.links:
        if url in seen:
            continue
        seen.add(url)
        lines.append(f"Start with – {_mdl(title, url)}" + (f"  ({src})" if src != e.official[0] else ""))
        n += 1
        if n >= max_learn:
            break
    return lines


def links_markdown(tool: str, seen: set[str] | None = None, max_learn: int = 4) -> str:
    seen = set() if seen is None else seen
    es = find_entries(tool)
    if not es:
        return (f"No curated link is stored for {tool}. Search for the official documentation site of {tool} "
                "(do not rely on unofficial copies).")
    lines: list[str] = []
    for e in es:
        lines += entry_lines(e, seen, max_learn)
    return "\n".join(lines) or "Same resources as listed above."


def links_block(names: list[str], limit: int = 8) -> str:
    """'Learning resources' block for chat answers about tools/libraries (verified catalog only; '' when nothing is known)."""
    seen: set[str] = set()
    out, shown = [], set()
    for n in names:
        for e in find_entries(n):
            if e.key in shown:
                continue
            shown.add(e.key)
            lines = entry_lines(e, seen, 2)
            if lines:
                out += [f"**{e.name}**"] + lines
            if len(shown) >= limit:
                break
    return ("\n\n**Learning resources (official sources)**\n" + "\n".join(out)) if out else ""


def tasks_using(tool: str, tasks: list[dict]) -> list[dict]:
    """Tasks whose declared tools (or text) mention this tool."""
    n = _norm(tool)
    hit = []
    for t in tasks:
        declared = [_norm(x) for x in t.get("tools", [])]
        text = _norm(" ".join([t["title"], t["description"], " ".join(t.get("subtasks", []))]))
        if n in declared or any(n in d or d in n for d in declared if len(d) > 2) or re.search(rf"(?<![\w]){re.escape(n)}(?![\w])", text):
            hit.append(t)
    return hit


def _task_ref(ts: list[dict]) -> str:
    return ", ".join(f"Task {t['position']}" for t in ts) if ts else "the project in general"


def base_note(tool: str, role: str, project: dict, position: int, total: int, tasks: list[dict]) -> str:
    """Complete non-AI note: what it is, why/where (from the plan), concepts, verified links, order. Instant, no LLM."""
    es = find_entries(tool)
    uses = tasks_using(tool, tasks)
    what = " ".join(e.what for e in es) or f"{tool} is one of the technologies recommended for this project."
    parts = [f"## 1. What is it?\n{what}",
             f"## 2. Why is it needed?\n{role or 'It is listed in the plan for this project.'}",
             f"## 3. Where is it used in this project?\nProject: {project['title']}. Needed for: {_task_ref(uses)}."]
    concepts = [c for e in es for c in e.concepts]
    if concepts:
        parts.append("## 4. Important concepts\n" + "\n".join(f"- {c}" for c in concepts))
    return "\n\n".join(parts)


def resource_sections(tool: str, position: int, total: int, tasks: list[dict], prev_tool: str = "", next_tool: str = "") -> str:
    uses = tasks_using(tool, tasks)
    order = f"Learn it as tool {position} of {total}."
    if prev_tool:
        order += f" Before this: {prev_tool}."
    if next_tool:
        order += f" After this: {next_tool}."
    if uses:
        order += f" Have the basics ready before {_task_ref(uses[:1])}."
    return f"## 8. Official documentation and learning resources\n{links_markdown(tool)}\n\n## 9. Suggested learning order\n{order}"


def offline_note(tool: str, role: str, doc_url: str, project: dict, position: int, total: int, tasks: list[dict] | None = None,
                 prev_tool: str = "", next_tool: str = "") -> str:
    """Offline note = catalog facts + local knowledge-base excerpts + verified links."""
    tasks = tasks or []
    chunks = retriever.retrieve(f"{tool} {project['title']}", k=2)
    parts = [f"# {tool}",
             "_Offline note (no AI model used). Press **Regenerate with AI** for a personalised beginner explanation._",
             base_note(tool, role, project, position, total, tasks)]
    if chunks:
        parts.append("## Reference excerpts (local knowledge base)\n" + "\n\n".join(f"**{c.source}**\n{c.text}" for c in chunks))
    parts.append(resource_sections(tool, position, total, tasks, prev_tool, next_tool))
    return "\n\n".join(parts)


def learning_path(project: dict, tools: list[dict], tasks: list[dict]) -> str:
    """Ordered reading list that ties every technology to the roadmap tasks that need it (only THIS project's tools)."""
    lines = [f"# Learning path - {project['title']}", "Read in this order. Each item lists the tasks that need it.", ""]
    active = next((t for t in tasks if t["status"] == "active"), None)
    if active and active.get("tools"):
        lines += [f"## Start here - Task {active['position']}: {active['title']}",
                  "Tools for your current task: " + ", ".join(active["tools"]), ""]
    seen: set[str] = set()
    for i, t in enumerate(tools, 1):
        uses = tasks_using(t["name"], tasks)
        lines.append(f"## {i}. {t['name']}  (needed for: {_task_ref(uses)})")
        es = find_entries(t["name"])
        for e in es:
            lines += entry_lines(e, seen, 2)
        if not es:
            lines.append("No curated link stored - search the official documentation site.")
        elif not any(x.startswith(("Official", "Start")) for x in lines[-6:]):
            lines.append("Same resources as listed above.")
        lines.append("")
    return "\n".join(lines).strip()


def chat_block(tools: list[dict], tasks: list[dict], max_tools: int = 12) -> str:
    """Deterministic 'Recommended tools and where to learn them' block shown with the project plan."""
    lines = ["## Recommended tools and where to learn them"]
    seen: set[str] = set()
    for t in tools[:max_tools]:
        es = find_entries(t["name"])
        uses = tasks_using(t["name"], tasks)
        lines.append(f"**{t['name']}** - {t['detail'] or (es[0].what if es else '')}  (used in: {_task_ref(uses)})")
        for e in es:
            lines += entry_lines(e, seen, 2)
        if not es:
            lines.append("No curated link available - search the official documentation site.")
    lines.append("Full notes for every tool are in the Learning Resources section.")
    return "\n".join(lines)


def prompt_block(tool_names: list[str], max_links: int = 3) -> str:
    """Compact verified-links text for the LLM (only used when the student asks about learning / documentation)."""
    out = []
    for n in tool_names:
        for e in find_entries(n):
            out.append(f"{e.name}: {e.official[0]} {e.official[1]} | " +
                       " | ".join(f"{t} ({s}) {u}" for t, u, s in e.links[:max_links] if u != e.official[1]))
    return "\n".join(out)
